                relationship.Row.PrimaryKey = RequireTarget(
                    loadIndexes.PrimaryKeyListById,
                    relationship.PrimaryKeyId,
                    "PrimaryKeyColumn",
                    relationship.Row.Id,
                    "PrimaryKeyId");
            }

            foreach (var relationship in relationshipBuffers.PrimaryKeyColumnRelationships ?? Enumerable.Empty<PrimaryKeyColumnRelationships>())
            {
                relationship.Row.TableColumn = RequireTarget(
                    loadIndexes.TableColumnListById,
                    relationship.TableColumnId,
                    "PrimaryKeyColumn",
                    relationship.Row.Id,
                    "TableColumnId");
            }

            foreach (var relationship in relationshipBuffers.SchemaRelationships ?? Enumerable.Empty<SchemaRelationships>())
            {
                relationship.Row.Database = RequireTarget(
                    loadIndexes.DatabaseListById,
                    relationship.DatabaseId,
                    "Schema",
                    relationship.Row.Id,
                    "DatabaseId");
            }

            foreach (var relationship in relationshipBuffers.StoredProcedureRelationships ?? Enumerable.Empty<StoredProcedureRelationships>())
            {
                relationship.Row.Schema = RequireTarget(
                    loadIndexes.SchemaListById,
                    relationship.SchemaId,
                    "StoredProcedure",
                    relationship.Row.Id,
                    "SchemaId");
            }

            foreach (var relationship in relationshipBuffers.TableRelationships ?? Enumerable.Empty<TableRelationships>())
            {
                relationship.Row.Schema = RequireTarget(
                    loadIndexes.SchemaListById,
                    relationship.SchemaId,
                    "Table",
                    relationship.Row.Id,
                    "SchemaId");
            }

            foreach (var relationship in relationshipBuffers.TableColumnRelationships ?? Enumerable.Empty<TableColumnRelationships>())
            {
                relationship.Row.Table = RequireTarget(
                    loadIndexes.TableListById,
                    relationship.TableId,
                    "TableColumn",
                    relationship.Row.Id,
                    "TableId");
            }

            foreach (var relationship in relationshipBuffers.TableColumnDataTypeDetailRelationships ?? Enumerable.Empty<TableColumnDataTypeDetailRelationships>())
            {
                relationship.Row.TableColumn = RequireTarget(
                    loadIndexes.TableColumnListById,
                    relationship.TableColumnId,
                    "TableColumnDataTypeDetail",
                    relationship.Row.Id,
                    "TableColumnId");
            }

            foreach (var relationship in relationshipBuffers.ViewRelationships ?? Enumerable.Empty<ViewRelationships>())
